    // NIS2 page
    'compliance.nis2.seo.title': 'NIS2 Compliance with Vulnerability Disclosure | Defend Denmark',
    'compliance.nis2.seo.description': 'Defend Denmark delivers Article 21(2)(e) vulnerability handling, Article 21(2)(f) effectiveness assessment, and Article 12 coordinated disclosure for essential and important entities under NIS2 / NIS2-loven.',
